window.BloomHelpData.register({"schema":1,"locale":"tr","nativeReviewRequired":true,"common":{"review":"Taslak çeviri. Ana dili konuşuru tarafından incelenmesi gerekiyor.","fallback":"Bazı yardım metinleri İngilizce gösteriliyor.","recovery":"Bir sorun olduğunda","availability":"Entegrasyon adayıdır; onaylanan derlemede desteği doğrulayın."},"routes":{"start":{"title":"Yeni sekme / başlangıç sayfası","summary":"Bir evren seçin, uygulama veya site açın ve başlangıç sayfasını düzenleyin.","step":"“Düzenle” seçeneğini açın. Bir panel tutamacını diğerinin üzerine sürükleyin veya iki tutamaç seçerek panellerin yerini değiştirin. Gerektiğinde “Geri al” ya da “Düzeni sıfırla” kullanın.","recovery":"Düzenler her evren için ayrı olarak bu cihazda tutulur. Depolama kullanılamıyorsa değişiklikler yalnızca bu ziyaret boyunca geçerlidir."},"passwords":{"title":"Parola yöneticisi (prototip arayüz; kasa yerel uygulama bileşenidir)","summary":"Kayıtlı oturum açma bilgilerini dikkatli kullanın.","step":"Kayıtlı bir hesabı seçmeden önce web sitesi adresini kontrol edin.","recovery":"Kasa kilitliyse desteklenen işlemle kilidini açın. Destek raporuna asla parola eklemeyin."},"settings":{"title":"Ayarlar","summary":"Gezinme tercihlerinizi ayarlayın.","step":"Her seferinde tek bir ayarı değiştirip sonucu kontrol edin.","recovery":"Onaylı bir test planını izlemiyorsanız deneysel JIT ve GPU ayarlarını kapalı tutun."},"https-only":{"title":"Yalnızca HTTPS modu"},"private":{"title":"Gizli gezinme"},"themes":{"title":"Ortak temalar","summary":"Uygulama paketinin görünümünü seçin.","step":"Kullanılabilir bir temayı önizleyip seçiminizi onaylayın.","recovery":"Bazı uygulamaların ortak ayarı izlemesi için entegrasyon çalışması gerekebilir."},"reader":{"title":"Okuma modu","summary":"Bir makaleyi daha az dikkat dağıtıcı öğeyle okuyun.","step":"Geçerli makale için Okuyucu’yu açın ve kullanılabilir metin kontrollerini ayarlayın.","recovery":"Bazı sayfaların içeriği çıkarılamaz; içerik eksikse özgün sayfaya dönün."},"media":{"title":"Medya Merkezi"},"downloads":{"title":"İndirmeler paneli","summary":"İndirmeleri izleyin ve yönetin.","step":"Her işin durumunu ve hedefini kontrol edin; dosyaları yalnızca indirme tamamlandıktan sonra açın.","recovery":"Bir iş başarısız olursa hata mesajını kaydedin. JDownloader isteğe bağlıdır ve Setup kontrollerini geçmelidir."},"notes":{"title":"Notlar"},"device-login":{"title":"Başka bir cihazda oturum açın"},"status":{"title":"Bloom Core durumu","summary":"Paketin hangi uygulamalarının yanıt verdiğini kontrol edin.","step":"Her uygulamayı açmadan önce durumunu okuyun.","recovery":"Bloom Core çalışmıyorsa ortak uygulama keşfi kullanılamayabilir; gösterilen hatayı saklayın."},"library":{"title":"Yer işaretleri ve geçmiş","summary":"Kaydedilmiş bağlantıları ve tarama geçmişini bulun.","step":"Yer İşaretleri veya Geçmiş’i seçin ve bir sonucu açmadan önce adresi kontrol edin.","recovery":"Yerel bir kaydı silmek, bir web sitesi hesabını veya o hesaba ait kayıtları kaldırmaz."},"translate":{"title":"Sayfayı çevir","summary":"Sayfayı İngilizce okuyun.","step":"Web sitesi adresini ve Google Translate bilgilendirmesini inceleyin. Yalnızca sayfa adresini göndermeyi kabul ediyorsanız devam edin.","recovery":"Sayfa değişirse bu paneli yeniden açın ve yeni sayfayı onaylayın. Çeviri hatalı olabilir; hassas içerik göndermekten kaçının."},"accessibility":{"title":"Erişilebilirlik ayarları","summary":"Arayüzü daha kolay okunur ve kullanılabilir yapın.","step":"Bu sürümdeki metin, kontrast veya hareket tercihlerini deneyin.","recovery":"Metin kesiliyorsa sayfayı, dili ve çözünürlüğü not edin."},"find":{"title":"Sayfada bul ve yakınlaştır","summary":"Geçerli sayfadaki sözcükleri bulun.","step":"Bir ifade girin ve eşleşmeler arasında ilerleyin.","recovery":"Gizli veya dinamik olarak yüklenen metin, sayfa onu yükleyene kadar görünmeyebilir."},"keyboard":{"title":"Kontrolcü klavyesi v2","summary":"Kontrolcünüzle metin girin.","step":"Hedef alana odaklanın, karakterleri seçin ve girişi onaylayın.","recovery":"Bir karakter yoksa etkin klavye düzenini kontrol edin."}}});
